{
  "name": "DLP6500数字微镜投影模块",
  "name_en": "DLP6500 Digital Micromirror Projection Module",
  "manufacturer": "Texas Instruments",
  "description": "这是一种基于数字微镜器件（DMD）的高速图案投影与空间光调制设备，可按位图或预定义序列输出光学图案。实验室中常用于结构光照明、图案投影、光学调制以及需要精确时序触发的成像和曝光实验。",
  "description_en": "This is a digital micromirror device (DMD) based high-speed pattern projection and spatial light modulation unit that outputs optical patterns from bitmaps or predefined sequences. In laboratories it is commonly used for structured illumination, pattern projection, optical modulation, and imaging or exposure experiments that require precise timing and triggering.",
  "tag_hints": [
    "DMD",
    "digital micromirror device",
    "pattern projection",
    "structured illumination",
    "spatial light modulation",
    "DLPC900",
    "triggered optical sequencing"
  ],
  "actions": [
    {
      "action_name": "auto-command",
      "description": "发送底层USB控制命令到DMD控制器。",
      "description_en": "Send a low-level USB control command to the DMD controller."
    },
    {
      "action_name": "auto-checkforerrors",
      "description": "检查设备返回的错误状态或错误报告。",
      "description_en": "Check error status or error reports returned by the device."
    },
    {
      "action_name": "auto-readreply",
      "description": "读取设备控制器返回的数据响应。",
      "description_en": "Read the data reply returned by the device controller."
    },
    {
      "action_name": "auto-idle_on",
      "description": "启用设备空闲模式。",
      "description_en": "Enable the device idle mode."
    },
    {
      "action_name": "auto-idle_off",
      "description": "关闭设备空闲模式。",
      "description_en": "Disable the device idle mode."
    },
    {
      "action_name": "auto-standby",
      "description": "将设备切换到待机状态。",
      "description_en": "Put the device into standby mode."
    },
    {
      "action_name": "auto-wakeup",
      "description": "将设备从待机状态唤醒。",
      "description_en": "Wake the device from standby mode."
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备控制器。",
      "description_en": "Reset the device controller."
    },
    {
      "action_name": "auto-testread",
      "description": "执行测试读取通信操作。",
      "description_en": "Perform a test read communication operation."
    },
    {
      "action_name": "auto-testwrite",
      "description": "执行测试写入通信操作。",
      "description_en": "Perform a test write communication operation."
    },
    {
      "action_name": "auto-changemode",
      "description": "切换设备的工作模式。",
      "description_en": "Change the operating mode of the device."
    },
    {
      "action_name": "auto-startsequence",
      "description": "启动图案序列投影。",
      "description_en": "Start pattern sequence projection."
    },
    {
      "action_name": "auto-pausesequence",
      "description": "暂停图案序列投影。",
      "description_en": "Pause pattern sequence projection."
    },
    {
      "action_name": "auto-stopsequence",
      "description": "停止图案序列投影。",
      "description_en": "Stop pattern sequence projection."
    },
    {
      "action_name": "auto-configurelut",
      "description": "配置图案序列的查找表和重复参数。",
      "description_en": "Configure the lookup table and repetition parameters for a pattern sequence."
    },
    {
      "action_name": "auto-definepattern",
      "description": "定义单个投影图案的时序、位深、颜色和触发参数。",
      "description_en": "Define the timing, bit depth, color, and trigger parameters of a single projected pattern."
    },
    {
      "action_name": "auto-setbmp",
      "description": "设置位图图像的索引和大小信息。",
      "description_en": "Set the index and size information for a bitmap image."
    },
    {
      "action_name": "auto-bmpload",
      "description": "向设备上传位图图像数据。",
      "description_en": "Upload bitmap image data to the device."
    },
    {
      "action_name": "auto-defsequence",
      "description": "定义由多幅图像及其曝光和触发时序组成的完整投影序列。",
      "description_en": "Define a complete projection sequence composed of multiple images with exposure and trigger timing."
    }
  ]
}

